INSERT INTO `ai_chan_doan_log` (`id`, `benh_nhan_id`, `nguoi_dung_id`, `trieu_chung_text`, `trieu_chung_json`, `ket_qua_json`, `muc_nguy_co`, `ngay_tao`) VALUES
(1, NULL, 1, '', '[{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]', '{\"detected_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}], \"results\": [{\"id\": \"influenza\", \"name\": \"Cúm mùa\", \"confidence\": 61, \"description\": \"Nhiễm virus cúm, thường khởi phát nhanh với sốt, đau đầu, đau mỏi người và ho.\", \"specialist\": \"Nội tổng quát\", \"advice\": \"Nghỉ ngơi, uống nước, khám sớm nếu người già, trẻ nhỏ, thai phụ hoặc có bệnh nền.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"common_cold\", \"name\": \"Cảm lạnh\", \"confidence\": 57, \"description\": \"Nhiễm virus đường hô hấp trên, thường gây sổ mũi, ho nhẹ, đau họng.\", \"specialist\": \"Nội tổng quát hoặc Tai Mũi Họng\", \"advice\": \"Nghỉ ngơi, uống đủ nước, theo dõi sốt. Khám nếu sốt cao hoặc kéo dài trên 3 ngày.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"bronchitis\", \"name\": \"Viêm phế quản\", \"confidence\": 51, \"description\": \"Viêm đường dẫn khí, gây ho kéo dài, khạc đờm, có thể kèm sốt nhẹ và khò khè.\", \"specialist\": \"Hô hấp\", \"advice\": \"Khám hô hấp nếu ho trên 1 tuần, đờm xanh/vàng, sốt hoặc khó thở.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}]}, {\"id\": \"asthma\", \"name\": \"Hen phế quản\", \"confidence\": 29, \"description\": \"Bệnh viêm mạn tính đường thở gây khò khè, khó thở từng cơn, ho về đêm.\", \"specialist\": \"Hô hấp\", \"advice\": \"Nên khám chuyên khoa hô hấp để đo chức năng phổi và có thuốc kiểm soát.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}]}, {\"id\": \"otitis\", \"name\": \"Viêm tai\", \"confidence\": 24, \"description\": \"Viêm tai giữa/ngoài gây đau tai, ù tai, có thể chảy dịch hoặc sốt.\", \"specialist\": \"Tai Mũi Họng\", \"advice\": \"Khám Tai Mũi Họng nếu đau tăng, chảy dịch hoặc nghe kém.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}]}], \"risk_level\": \"medium\", \"advice\": \"Co the dat lich voi bac si Nội tổng quát de duoc hoi benh va kham truc tiep.\", \"disclaimer\": \"Ket qua chi ho tro sang loc ban dau, khong thay the chan doan cua bac si.\"}', 'medium', '2026-05-12 13:25:17'),
