(52, 1, 102, '', '[{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]', '{\"detected_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}], \"results\": [{\"id\": \"influenza\", \"name\": \"Cúm mùa\", \"confidence\": 61, \"description\": \"Nhiễm virus cúm, thường khởi phát nhanh với sốt, đau đầu, đau mỏi người và ho.\", \"specialist\": \"Nội tổng quát\", \"advice\": \"Nghỉ ngơi, uống nước, khám sớm nếu người già, trẻ nhỏ, thai phụ hoặc có bệnh nền.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"common_cold\", \"name\": \"Cảm lạnh\", \"confidence\": 57, \"description\": \"Nhiễm virus đường hô hấp trên, thường gây sổ mũi, ho nhẹ, đau họng.\", \"specialist\": \"Nội tổng quát hoặc Tai Mũi Họng\", \"advice\": \"Nghỉ ngơi, uống đủ nước, theo dõi sốt. Khám nếu sốt cao hoặc kéo dài trên 3 ngày.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"bronchitis\", \"name\": \"Viêm phế quản\", \"confidence\": 51, \"description\": \"Viêm đường dẫn khí, gây ho kéo dài, khạc đờm, có thể kèm sốt nhẹ và khò khè.\", \"specialist\": \"Hô hấp\", \"advice\": \"Khám hô hấp nếu ho trên 1 tuần, đờm xanh/vàng, sốt hoặc khó thở.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}]}, {\"id\": \"asthma\", \"name\": \"Hen phế quản\", \"confidence\": 29, \"description\": \"Bệnh viêm mạn tính đường thở gây khò khè, khó thở từng cơn, ho về đêm.\", \"specialist\": \"Hô hấp\", \"advice\": \"Nên khám chuyên khoa hô hấp để đo chức năng phổi và có thuốc kiểm soát.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}]}, {\"id\": \"otitis\", \"name\": \"Viêm tai\", \"confidence\": 24, \"description\": \"Viêm tai giữa/ngoài gây đau tai, ù tai, có thể chảy dịch hoặc sốt.\", \"specialist\": \"Tai Mũi Họng\", \"advice\": \"Khám Tai Mũi Họng nếu đau tăng, chảy dịch hoặc nghe kém.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}]}], \"risk_level\": \"medium\", \"advice\": \"Co the dat lich voi bac si Nội tổng quát de duoc hoi benh va kham truc tiep.\", \"disclaimer\": \"Ket qua chi ho tro sang loc ban dau, khong thay the chan doan cua bac si.\"}', 'medium', '2026-05-12 13:39:42'),
(53, 1, 102, '', '[{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"runny_nose\", \"label\": \"Sổ mũi/nghẹt mũi\", \"specialist_hint\": \"Tai Mũi Họng\"}, {\"id\": \"palpitation\", \"label\": \"Hồi hộp/trống ngực\", \"specialist_hint\": \"Tim mạch\"}, {\"id\": \"nausea\", \"label\": \"Buồn nôn\", \"specialist_hint\": \"Tiêu hóa\"}, {\"id\": \"constipation\", \"label\": \"Táo bón\", \"specialist_hint\": \"Tiêu hóa\"}]', '{\"detected_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"runny_nose\", \"label\": \"Sổ mũi/nghẹt mũi\", \"specialist_hint\": \"Tai Mũi Họng\"}, {\"id\": \"palpitation\", \"label\": \"Hồi hộp/trống ngực\", \"specialist_hint\": \"Tim mạch\"}, {\"id\": \"nausea\", \"label\": \"Buồn nôn\", \"specialist_hint\": \"Tiêu hóa\"}, {\"id\": \"constipation\", \"label\": \"Táo bón\", \"specialist_hint\": \"Tiêu hóa\"}], \"results\": [{\"id\": \"common_cold\", \"name\": \"Cảm lạnh\", \"confidence\": 44, \"description\": \"Nhiễm virus đường hô hấp trên, thường gây sổ mũi, ho nhẹ, đau họng.\", \"specialist\": \"Nội tổng quát hoặc Tai Mũi Họng\", \"advice\": \"Nghỉ ngơi, uống đủ nước, theo dõi sốt. Khám nếu sốt cao hoặc kéo dài trên 3 ngày.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"runny_nose\", \"label\": \"Sổ mũi/nghẹt mũi\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"gastroenteritis\", \"name\": \"Viêm dạ dày ruột cấp\", \"confidence\": 34, \"description\": \"Rối loạn tiêu hóa do virus, vi khuẩn hoặc thức ăn, gây đau bụng, tiêu chảy, nôn.\", \"specialist\": \"Tiêu hóa\", \"advice\": \"Bù nước điện giải, ăn nhẹ. Khám nếu tiêu chảy nhiều, sốt cao, mất nước hoặc phân máu.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"nausea\", \"label\": \"Buồn nôn\", \"specialist_hint\": \"Tiêu hóa\"}]}, {\"id\": \"influenza\", \"name\": \"Cúm mùa\", \"confidence\": 28, \"description\": \"Nhiễm virus cúm, thường khởi phát nhanh với sốt, đau đầu, đau mỏi người và ho.\", \"specialist\": \"Nội tổng quát\", \"advice\": \"Nghỉ ngơi, uống nước, khám sớm nếu người già, trẻ nhỏ, thai phụ hoặc có bệnh nền.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}]}, {\"id\": \"hyperthyroid_risk\", \"name\": \"Nguy cơ cường giáp\", \"confidence\": 28, \"description\": \"Tuyến giáp hoạt động quá mức có thể gây sụt cân, hồi hộp, run tay, mất ngủ.\", \"specialist\": \"Nội tiết\", \"advice\": \"Nên khám nội tiết và xét nghiệm chức năng tuyến giáp.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"palpitation\", \"label\": \"Hồi hộp/trống ngực\", \"specialist_hint\": \"Tim mạch\"}]}, {\"id\": \"otitis\", \"name\": \"Viêm tai\", \"confidence\": 24, \"description\": \"Viêm tai giữa/ngoài gây đau tai, ù tai, có thể chảy dịch hoặc sốt.\", \"specialist\": \"Tai Mũi Họng\", \"advice\": \"Khám Tai Mũi Họng nếu đau tăng, chảy dịch hoặc nghe kém.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}]}], \"risk_level\": \"low\", \"advice\": \"Theo doi them, nghi ngoi va dat lich kham neu trieu chung keo dai tren 2-3 ngay.\", \"disclaimer\": \"Ket qua chi ho tro sang loc ban dau, khong thay the chan doan cua bac si.\"}', 'low', '2026-05-12 13:41:11'),
(54, 1, 102, '', '[{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]', '{\"detected_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}], \"results\": [{\"id\": \"influenza\", \"name\": \"Cúm mùa\", \"confidence\": 61, \"description\": \"Nhiễm virus cúm, thường khởi phát nhanh với sốt, đau đầu, đau mỏi người và ho.\", \"specialist\": \"Nội tổng quát\", \"advice\": \"Nghỉ ngơi, uống nước, khám sớm nếu người già, trẻ nhỏ, thai phụ hoặc có bệnh nền.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"common_cold\", \"name\": \"Cảm lạnh\", \"confidence\": 57, \"description\": \"Nhiễm virus đường hô hấp trên, thường gây sổ mũi, ho nhẹ, đau họng.\", \"specialist\": \"Nội tổng quát hoặc Tai Mũi Họng\", \"advice\": \"Nghỉ ngơi, uống đủ nước, theo dõi sốt. Khám nếu sốt cao hoặc kéo dài trên 3 ngày.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"fever\", \"label\": \"Sốt\", \"specialist_hint\": \"Nội tổng quát\"}, {\"id\": \"cough\", \"label\": \"Ho\", \"specialist_hint\": \"Hô hấp\"}, {\"id\": \"sore_throat\", \"label\": \"Đau họng\", \"specialist_hint\": \"Tai Mũi Họng\"}]}, {\"id\": \"bronchitis\", \"name\": \"Viêm phế quản\", \"confidence\": 51, \"description\": \"Viêm đường dẫn khí, gây ho kéo dài, khạc đờm, có thể kèm sốt nhẹ và khò khè.\", \"specialist\": \"Hô hấp\", \"advice\": \"Khám hô hấp nếu ho trên 1 tuần, đờm xanh/