(56, 1, 102, '', '[{\"id\": \"constipation\", \"label\": \"Táo bón\", \"specialist_hint\": \"Tiêu hóa\"}, {\"id\": \"heartburn\", \"label\": \"Ợ nóng/ợ chua\", \"specialist_hint\": \"Tiêu hóa\"}, {\"id\": \"rash\", \"label\": \"Phát ban\", \"specialist_hint\": \"Da liễu\"}]', '{\"detected_symptoms\": [{\"id\": \"constipation\", \"label\": \"Táo bón\", \"specialist_hint\": \"Tiêu hóa\"}, {\"id\": \"heartburn\", \"label\": \"Ợ nóng/ợ chua\", \"specialist_hint\": \"Tiêu hóa\"}, {\"id\": \"rash\", \"label\": \"Phát ban\", \"specialist_hint\": \"Da liễu\"}], \"results\": [{\"id\": \"gastritis_reflux\", \"name\": \"Viêm dạ dày/trào ngược\", \"confidence\": 43, \"description\": \"Tình trạng kích ứng dạ dày hoặc trào ngược acid gây đau thượng vị, ợ nóng, buồn nôn.\", \"specialist\": \"Tiêu hóa\", \"advice\": \"Tránh ăn khuya, cà phê, rượu bia, đồ cay. Khám tiêu hóa nếu đau kéo dài.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"heartburn\", \"label\": \"Ợ nóng/ợ chua\", \"specialist_hint\": \"Tiêu hóa\"}]}, {\"id\": \"urticaria\", \"name\": \"Mề đay/dị ứng da\", \"confidence\": 42, \"description\": \"Phản ứng dị ứng gây nổi mẩn, ngứa, phù nhẹ từng mảng.\", \"specialist\": \"Da liễu hoặc Dị ứng\", \"advice\": \"Tránh tác nhân nghi ngờ. Đi cấp cứu nếu phù môi, khó thở hoặc chóng mặt.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"rash\", \"label\": \"Phát ban\", \"specialist_hint\": \"Da liễu\"}]}, {\"id\": \"acne_vulgaris\", \"name\": \"Mụn trứng cá\", \"confidence\": 25, \"description\": \"Viêm nang lông tuyến bã, thường gặp ở mặt, ngực, lưng.\", \"specialist\": \"Da liễu\", \"advice\": \"Không tự nặn mụn viêm. Khám da liễu nếu mụn mủ, sẹo hoặc kéo dài.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"rash\", \"label\": \"Phát ban\", \"specialist_hint\": \"Da liễu\"}]}, {\"id\": \"ibs\", \"name\": \"Hội chứng ruột kích thích\", \"confidence\": 22, \"description\": \"Rối loạn chức năng ruột gây đau bụng tái diễn, tiêu chảy hoặc táo bón liên quan stress/thức ăn.\", \"specialist\": \"Tiêu hóa\", \"advice\": \"Theo dõi thức ăn gây triệu chứng, tăng chất xơ phù hợp và khám nếu kéo dài.\", \"red_flags\": [], \"matched_symptoms\": [{\"id\": \"constipation\", \"label\": \"Táo bón\", \"specialist_hint\": \"Tiêu hóa\"}]}], \"risk_level\": \"low\", \"advice\": \"Theo doi them, nghi ngoi va dat lich kham neu trieu chung keo dai tren 2-3 ngay.\", \"disclaimer\": \"Ket qua chi ho tro sang loc ban dau, khong thay the chan doan cua bac si.\"}', 'low', '2026-05-12 14:40:57');
